/* GreenBean Coffee — Design System */
:root {
  /* Brand Colors (OKLCH) */
  --green-primary: oklch(45% 0.14 160);
  --green-dark: oklch(30% 0.06 145);
  --cream-warm: oklch(88% 0.05 75);
  --cream-light: oklch(96% 0.02 85);
  --brown-rich: oklch(35% 0.08 55);
  --brown-medium: oklch(50% 0.08 55);
  --white: oklch(99% 0 0);
  --off-white: oklch(97% 0.005 85);
  --black: oklch(15% 0.01 0);
  --gray-100: oklch(95% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(80% 0.005 0);
  --gray-400: oklch(65% 0.005 0);
  --gray-500: oklch(50% 0.01 0);
  --gray-600: oklch(40% 0.01 0);
  --gray-700: oklch(30% 0.01 0);
  --gold: oklch(72% 0.16 80);
  --gold-light: oklch(88% 0.08 80);
  --reserve-purple: oklch(45% 0.18 300);
  --reserve-light: oklch(90% 0.06 300);
  --accent-coral: oklch(70% 0.16 30);
  --accent-mango: oklch(78% 0.16 70);
  --accent-lavender: oklch(70% 0.12 290);
  --accent-blue: oklch(60% 0.14 250);

  /* Typography */
  --font-body: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Fraunces', 'Georgia', serif;

  /* Spacing Scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 30px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 50px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 80px;
}

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300..700;1,9..40,300..700&family=Fraunces:ital,opsz,wght@0,9..144,300..700;1,9..144,300..700&display=swap');

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  color: var(--black);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.2; font-weight: 600; }

/* Utility */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-lg); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-sm { gap: var(--space-sm); }
.gap-md { gap: var(--space-md); }
.gap-lg { gap: var(--space-lg); }
.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition-base);
  white-space: nowrap;
  letter-spacing: 0.01em;
}
.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}
.btn-primary:hover { background: oklch(40% 0.14 160); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline {
  border: 2px solid var(--green-primary);
  color: var(--green-primary);
  background: transparent;
}
.btn-outline:hover { background: var(--green-primary); color: var(--white); }
.btn-dark {
  background: var(--black);
  color: var(--white);
}
.btn-dark:hover { background: oklch(25% 0.01 0); transform: translateY(-1px); }
.btn-white {
  background: var(--white);
  color: var(--green-primary);
}
.btn-white:hover { background: var(--cream-light); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }
.btn-lg { padding: 16px 32px; font-size: 1.05rem; }

/* ============ HEADER ============ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}
.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.35rem;
  color: var(--green-primary);
}
.logo-icon {
  width: 44px;
  height: 44px;
  background: var(--green-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-main { display: flex; align-items: center; gap: var(--space-xl); }
.nav-main a {
  font-weight: 500;
  font-size: 0.938rem;
  color: var(--gray-700);
  transition: color var(--transition-fast);
  padding: var(--space-sm) 0;
  position: relative;
}
.nav-main a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-base);
}
.nav-main a:hover { color: var(--green-primary); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green-primary); }
.nav-main a.active::after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: var(--space-md); }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 22px; height: 16px; display: flex; flex-direction: column; justify-content: space-between; }
.hamburger span { display: block; height: 2px; background: var(--black); border-radius: 2px; transition: var(--transition-base); }

/* ============ HERO ============ */
.hero {
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  padding: var(--space-4xl) 0;
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.hero::before {
  content: '';
  position: absolute;
  right: -5%;
  top: -10%;
  width: 55%;
  height: 120%;
  background: radial-gradient(ellipse, oklch(45% 0.14 160 / 0.08), transparent 70%);
  border-radius: 50%;
}
.hero-content { max-width: 560px; position: relative; z-index: 1; }
.hero h1 {
  font-size: clamp(2.5rem, 5vw, 3.8rem);
  color: var(--green-dark);
  margin-bottom: var(--space-lg);
  font-weight: 700;
}
.hero p {
  font-size: 1.15rem;
  color: var(--gray-600);
  margin-bottom: var(--space-xl);
  max-width: 440px;
}
.hero-image-placeholder {
  position: absolute;
  right: 5%;
  top: 50%;
  transform: translateY(-50%);
  width: 420px;
  height: 420px;
  background: linear-gradient(145deg, oklch(45% 0.14 160 / 0.12), oklch(88% 0.05 75 / 0.5));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green-primary);
  font-size: 3rem;
}

/* ============ SECTIONS ============ */
.section { padding: var(--space-4xl) 0; }
.section-alt { background: var(--off-white); }
.section-green { background: var(--green-primary); color: var(--white); }
.section-cream { background: var(--cream-light); }
.section-dark { background: var(--green-dark); color: var(--white); }
.section-title {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  margin-bottom: var(--space-md);
}
.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin-bottom: var(--space-2xl);
}

/* ============ PROMO CARDS ============ */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-2xl);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.promo-card h3 {
  font-size: 1.6rem;
  margin-bottom: var(--space-sm);
  color: inherit;
}
.promo-card p {
  margin-bottom: var(--space-lg);
  line-height: 1.5;
  opacity: 0.9;
}
.promo-card--citrus {
  background: linear-gradient(135deg, oklch(85% 0.12 70), oklch(90% 0.08 50));
  color: var(--brown-rich);
}
.promo-card--afternoon {
  background: linear-gradient(135deg, oklch(75% 0.1 30), oklch(85% 0.06 40));
  color: var(--brown-rich);
}
.promo-card--ai {
  background: linear-gradient(135deg, var(--green-dark), oklch(25% 0.08 160));
  color: var(--white);
}
.promo-card--fruity {
  background: linear-gradient(135deg, oklch(82% 0.14 60), oklch(75% 0.18 35));
  color: var(--brown-rich);
}
.promo-card--spring {
  background: linear-gradient(135deg, oklch(80% 0.12 290), oklch(85% 0.08 170));
  color: var(--green-dark);
}
.promo-card--nondairy {
  background: linear-gradient(135deg, var(--cream-warm), oklch(90% 0.04 85));
  color: var(--brown-rich);
}
.promo-card--full {
  grid-column: 1 / -1;
  min-height: 320px;
  text-align: center;
  align-items: center;
}

/* Image placeholder for promo cards */
.promo-image-placeholder {
  width: 100%;
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  opacity: 0.6;
}

/* ============ MENU PAGE ============ */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  padding: var(--space-2xl) 0;
}
.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-lg));
  align-self: start;
  max-height: calc(100vh - var(--header-height) - var(--space-2xl));
  overflow-y: auto;
}
.menu-sidebar-section { margin-bottom: var(--space-lg); }
.menu-sidebar-title {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: var(--space-sm);
  padding-left: var(--space-sm);
}
.menu-sidebar a {
  display: block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.938rem;
  color: var(--gray-600);
  transition: all var(--transition-fast);
}
.menu-sidebar a:hover { background: var(--gray-100); color: var(--green-primary); }
.menu-sidebar a.active { background: oklch(45% 0.14 160 / 0.08); color: var(--green-primary); font-weight: 600; }

.menu-category { margin-bottom: var(--space-3xl); }
.menu-category-title {
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--gray-200);
}
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-lg);
}
.menu-item {
  text-align: center;
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  cursor: pointer;
}
.menu-item:hover { background: var(--gray-100); transform: translateY(-2px); }
.menu-item-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto var(--space-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.menu-item-name { font-weight: 600; font-size: 0.9rem; }

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 0.85rem;
  color: var(--gray-400);
}
.breadcrumb a { color: var(--gray-500); }
.breadcrumb a:hover { color: var(--green-primary); text-decoration: underline; }
.breadcrumb span { margin: 0 var(--space-sm); }

/* ============ REWARDS PAGE ============ */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary), oklch(38% 0.16 165));
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
}
.rewards-hero h1 { font-size: clamp(2rem, 4vw, 3rem); margin-bottom: var(--space-md); }
.rewards-hero p { font-size: 1.15rem; max-width: 550px; margin: 0 auto var(--space-xl); opacity: 0.9; }

.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  text-align: center;
}
.hiw-step {
  padding: var(--space-xl);
}
.hiw-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green-primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0 auto var(--space-lg);
}
.hiw-step h3 { font-size: 1.2rem; margin-bottom: var(--space-sm); }
.hiw-step p { color: var(--gray-500); font-size: 0.95rem; }

/* Tiers */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}
.tier-card {
  border-radius: var(--radius-lg);
  padding: var(--space-2xl);
  text-align: center;
  border: 2px solid var(--gray-200);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}
.tier-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.tier-card--green { border-color: var(--green-primary); }
.tier-card--green .tier-badge { background: var(--green-primary); }
.tier-card--gold { border-color: var(--gold); }
.tier-card--gold .tier-badge { background: var(--gold); }
.tier-card--reserve { border-color: var(--reserve-purple); }
.tier-card--reserve .tier-badge { background: var(--reserve-purple); color: var(--white); }
.tier-badge {
  display: inline-block;
  padding: 6px 20px;
  border-radius: var(--radius-full);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
  margin-bottom: var(--space-lg);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.tier-stars { font-family: var(--font-heading); font-size: 1.6rem; font-weight: 700; margin-bottom: var(--space-sm); }
.tier-threshold { color: var(--gray-500); font-size: 0.9rem; margin-bottom: var(--space-lg); }
.tier-benefits { text-align: left; }
.tier-benefits li {
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}
.tier-benefits li::before {
  content: '\2713';
  color: var(--green-primary);
  font-weight: 700;
  flex-shrink: 0;
}
.tier-card--gold .tier-benefits li::before { color: var(--gold); }
.tier-card--reserve .tier-benefits li::before { color: var(--reserve-purple); }

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}
.redemption-tab {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  border: 2px solid var(--gray-200);
  background: var(--white);
  color: var(--gray-600);
  transition: all var(--transition-base);
}
.redemption-tab:hover { border-color: var(--green-primary); color: var(--green-primary); }
.redemption-tab.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
}
.redemption-content {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl);
  background: var(--off-white);
  border-radius: var(--radius-lg);
  min-height: 180px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.redemption-panel { display: none; }
.redemption-panel.active { display: flex; flex-direction: column; align-items: center; gap: var(--space-md); }
.redemption-stars {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--green-primary);
}
.redemption-reward { font-size: 1.15rem; font-weight: 500; }
.redemption-value { font-size: 0.9rem; color: var(--gray-500); }

/* Partnerships */
.partner-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.partner-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: var(--transition-base);
}
.partner-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}
.partner-card h4 { font-size: 1.05rem; margin-bottom: 4px; }
.partner-card p { font-size: 0.9rem; color: var(--gray-500); }

/* App Download */
.app-download {
  text-align: center;
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  border-radius: var(--radius-lg);
  padding: var(--space-3xl);
}
.app-badges { display: flex; gap: var(--space-md); justify-content: center; margin-top: var(--space-lg); }
.app-badge {
  padding: 12px 24px;
  background: var(--black);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.85rem;
  transition: var(--transition-base);
}
.app-badge:hover { background: oklch(25% 0 0); transform: translateY(-2px); }

/* ============ GIFT CARDS PAGE ============ */
.gift-hero {
  background: linear-gradient(135deg, oklch(80% 0.12 160), oklch(88% 0.05 75));
  padding: var(--space-4xl) 0;
  text-align: center;
}
.gift-hero h1 { font-size: clamp(2rem, 4vw, 3rem); color: var(--green-dark); margin-bottom: var(--space-md); }
.gift-hero p { font-size: 1.15rem; color: var(--gray-600); max-width: 550px; margin: 0 auto; }

.carousel-section { padding: var(--space-2xl) 0; }
.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}
.carousel-header h2 { font-size: 1.5rem; }
.carousel-nav { display: flex; gap: var(--space-sm); }
.carousel-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-base);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--green-primary); color: var(--green-primary); background: oklch(45% 0.14 160 / 0.05); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}
.gift-card {
  min-width: 220px;
  flex-shrink: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.gift-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.gift-card-image {
  width: 100%;
  aspect-ratio: 1.58;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--white);
  padding: var(--space-md);
  text-align: center;
}
.gift-card-label {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.85rem;
  font-weight: 500;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-top: none;
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

/* Gift card color themes */
.gc-spring { background: linear-gradient(135deg, oklch(72% 0.14 160), oklch(80% 0.10 130)); }
.gc-perk { background: linear-gradient(135deg, oklch(65% 0.12 30), oklch(75% 0.10 50)); }
.gc-friends { background: linear-gradient(135deg, oklch(55% 0.16 265), oklch(65% 0.12 280)); }
.gc-thankyou { background: linear-gradient(135deg, oklch(70% 0.14 80), oklch(78% 0.10 70)); }
.gc-star { background: linear-gradient(135deg, oklch(72% 0.16 80), oklch(65% 0.14 50)); }
.gc-work { background: linear-gradient(135deg, oklch(45% 0.14 160), oklch(50% 0.12 145)); }
.gc-birthday { background: linear-gradient(135deg, oklch(70% 0.18 330), oklch(75% 0.14 350)); }
.gc-celebrate { background: linear-gradient(135deg, oklch(68% 0.16 290), oklch(75% 0.12 310)); }
.gc-cheers { background: linear-gradient(135deg, oklch(60% 0.14 250), oklch(68% 0.10 265)); }
.gc-yay { background: linear-gradient(135deg, oklch(78% 0.16 70), oklch(72% 0.18 40)); }
.gc-treat { background: linear-gradient(135deg, oklch(50% 0.10 145), oklch(58% 0.08 160)); }
.gc-heritage { background: linear-gradient(135deg, oklch(35% 0.08 55), oklch(42% 0.10 40)); }
.gc-encourage { background: linear-gradient(135deg, oklch(75% 0.10 160), oklch(82% 0.06 140)); }
.gc-gotthis { background: linear-gradient(135deg, oklch(60% 0.18 30), oklch(68% 0.14 50)); }

/* Business Gifting */
.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2xl);
  align-items: center;
  padding: var(--space-3xl);
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-lg);
}
.business-gifting h2 { font-size: 1.8rem; margin-bottom: var(--space-md); }
.business-gifting p { opacity: 0.85; margin-bottom: var(--space-lg); line-height: 1.6; }
.business-image-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: oklch(25% 0.06 145 / 0.5);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: oklch(80% 0.04 160);
}

/* eGift Info */
.egift-info {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.egift-info p { color: var(--gray-500); line-height: 1.7; margin-bottom: var(--space-md); }
.egift-actions { display: flex; gap: var(--space-md); justify-content: center; flex-wrap: wrap; }
.egift-link {
  color: var(--green-primary);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.egift-link:hover { color: oklch(38% 0.14 160); }

/* ============ STORE LOCATOR ============ */
.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  min-height: calc(100vh - var(--header-height));
}
.locator-panel {
  padding: var(--space-xl);
  overflow-y: auto;
  border-right: 1px solid var(--gray-200);
}
.locator-search {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}
.locator-search input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.938rem;
  font-family: var(--font-body);
  transition: border-color var(--transition-fast);
  outline: none;
}
.locator-search input:focus { border-color: var(--green-primary); }
.locator-search input::placeholder { color: var(--gray-400); }
.filter-btn {
  padding: 12px 20px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.85rem;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  transition: all var(--transition-fast);
}
.filter-btn:hover { border-color: var(--green-primary); color: var(--green-primary); }
.filter-btn.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.order-type-toggle {
  display: flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-lg);
}
.order-type-btn {
  flex: 1;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  text-align: center;
  transition: all var(--transition-base);
  color: var(--gray-500);
}
.order-type-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--gray-100);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
}
.filter-panel.open { display: block; }
.filter-panel h4 { font-size: 0.9rem; margin-bottom: var(--space-sm); }
.filter-options { display: flex; flex-wrap: wrap; gap: var(--space-sm); }
.filter-chip {
  padding: 6px 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.filter-chip:hover, .filter-chip.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.search-suggestions {
  display: none;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-top: -var(--space-md);
  margin-bottom: var(--space-md);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.search-suggestions.open { display: block; }
.suggestion-item {
  padding: 12px 16px;
  cursor: pointer;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--gray-100);
  transition: background var(--transition-fast);
}
.suggestion-item:hover { background: var(--gray-100); }
.suggestion-item:last-child { border-bottom: none; }

.store-list { display: flex; flex-direction: column; }
.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--gray-200);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.store-card:hover { background: var(--gray-100); }
.store-card h4 { font-size: 1rem; margin-bottom: 4px; }
.store-card .store-address { font-size: 0.85rem; color: var(--gray-500); margin-bottom: 4px; }
.store-card .store-hours { font-size: 0.82rem; color: var(--gray-400); margin-bottom: var(--space-sm); }
.store-features { display: flex; gap: var(--space-sm); flex-wrap: wrap; }
.store-feature {
  font-size: 0.75rem;
  padding: 3px 10px;
  background: oklch(45% 0.14 160 / 0.08);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-weight: 500;
}

.map-container {
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.map-placeholder {
  width: 100%;
  height: 100%;
  min-height: 400px;
  background:
    linear-gradient(90deg, var(--gray-200) 1px, transparent 1px),
    linear-gradient(var(--gray-200) 1px, transparent 1px),
    var(--gray-100);
  background-size: 60px 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 1.1rem;
  flex-direction: column;
  gap: var(--space-sm);
}
.map-pin {
  width: 36px;
  height: 36px;
  background: var(--green-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  position: absolute;
  box-shadow: var(--shadow-md);
}
.map-pin::after {
  content: '';
  width: 14px;
  height: 14px;
  background: var(--white);
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* ============ FOOTER ============ */
.site-footer {
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: var(--space-3xl) 0 var(--space-xl);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}
.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-md);
  color: var(--black);
}
.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--gray-500);
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--green-primary); }
.footer-toggle { display: none; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-xl);
  border-top: 1px solid var(--gray-200);
  font-size: 0.82rem;
  color: var(--gray-400);
}
.footer-social { display: flex; gap: var(--space-md); }
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-fast);
  font-size: 0.85rem;
}
.footer-social a:hover { background: var(--green-primary); color: var(--white); }
.footer-legal { display: flex; gap: var(--space-lg); }
.footer-legal a:hover { color: var(--green-primary); }

/* ============ COOKIE BANNER ============ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px oklch(0% 0 0 / 0.12);
  padding: var(--space-lg) var(--space-xl);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
  transition: transform var(--transition-slow);
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-text h4 { font-family: var(--font-body); font-size: 0.95rem; font-weight: 700; margin-bottom: 4px; }
.cookie-text p { font-size: 0.85rem; color: var(--gray-500); }
.cookie-actions { display: flex; gap: var(--space-md); flex-shrink: 0; }

/* ============ MOBILE NAV ============ */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: var(--space-xl);
  flex-direction: column;
  gap: var(--space-md);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  padding: var(--space-md);
  font-size: 1.15rem;
  font-weight: 500;
  border-bottom: 1px solid var(--gray-100);
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .hero-image-placeholder { width: 320px; height: 320px; right: 2%; }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-panel { border-right: none; border-bottom: 1px solid var(--gray-200); }
  .map-container { min-height: 400px; }
  .business-gifting { grid-template-columns: 1fr; text-align: center; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }
  .nav-main, .nav-actions .btn { display: none; }
  .mobile-menu-btn { display: flex; }
  .hero { padding: var(--space-2xl) 0; min-height: auto; }
  .hero-image-placeholder { display: none; }
  .hero h1 { font-size: 2rem; }
  .promo-grid { grid-template-columns: 1fr; }
  .promo-card { min-height: 280px; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; overflow-x: auto; gap: var(--space-sm); padding-bottom: var(--space-md); border-bottom: 1px solid var(--gray-200); margin-bottom: var(--space-lg); max-height: none; }
  .menu-sidebar-section { margin-bottom: 0; display: flex; gap: var(--space-xs); }
  .menu-sidebar-title { display: none; }
  .menu-sidebar a { white-space: nowrap; padding: 6px 14px; border: 1px solid var(--gray-200); border-radius: var(--radius-full); font-size: 0.82rem; }
  .how-it-works-grid { grid-template-columns: 1fr; gap: var(--space-md); }
  .tiers-grid { grid-template-columns: 1fr; }
  .partner-cards { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-md) 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--gray-200);
    cursor: pointer;
  }
  .footer-col h4::after { content: '+'; font-size: 1.2rem; font-weight: 400; }
  .footer-col.open h4::after { content: '\2212'; }
  .footer-col .footer-links { display: none; padding: var(--space-sm) 0; }
  .footer-col.open .footer-links { display: block; }
  .footer-toggle { display: block; }
  .footer-bottom { flex-direction: column; gap: var(--space-md); text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 14px; font-size: 0.82rem; }
  .locator-layout { grid-template-columns: 1fr; }
  .gift-card { min-width: 180px; }
  .section { padding: var(--space-2xl) 0; }
  .app-badges { flex-direction: column; align-items: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .menu-grid { grid-template-columns: repeat(2, 1fr); gap: var(--space-md); }
  .menu-item-image { width: 80px; height: 80px; }
  .gift-card { min-width: 160px; }
}

/* GreenBean Coffee — Design System */
:root {
  /* Brand Colors (OKLCH) */
  --green-primary: oklch(45% 0.14 160);
  --green-dark: oklch(30% 0.06 145);
  --cream-warm: oklch(88% 0.05 75);
  --cream-light: oklch(96% 0.02 85);
  --brown-rich: oklch(35% 0.08 55);
  --brown-medium: oklch(50% 0.08 55);
  --white: oklch(99% 0 0);
  --off-white: oklch(97% 0.005 85);
  --black: oklch(15% 0.01 0);
  --gray-100: oklch(95% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(80% 0.005 0);
  --gray-400: oklch(65% 0.005 0);
  --gray-500: oklch(50% 0.01 0);
  --gray-600: oklch(40% 0.01 0);
  --gray-700: oklch(30% 0.01 0);
  --gold: oklch(72% 0.16 80);
  --gold-light: oklch(88% 0.08 80);
  --reserve-purple: oklch(45% 0.18 300);
  --reserve-light: oklch(90% 0.06 300);
  --accent-coral: oklch(70% 0.16 30);
  --accent-mango: oklch(78% 0.16 70);
  --accent-lavender: oklch(70% 0.12 290);
  --accent-blue: oklch(60% 0.14 250);

  /* Typography */
  --font-body: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Fraunces', 'Georgia', serif;

  /* Spacing Scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 30px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 50px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 80px;
}

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300..700;1,9..40,300..700&family=Fraunces:ital,opsz,wght@0,9..144,300..700;1,9..144,300..700&display=swap');

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  color: var(--black);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.2; font-weight: 600; }

/* Utility */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-lg); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-sm { gap: var(--space-sm); }
.gap-md { gap: var(--space-md); }
.gap-lg { gap: var(--space-lg); }
.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition-base);
  white-space: nowrap;
  letter-spacing: 0.01em;
}
.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}
.btn-primary:hover { background: oklch(40% 0.14 160); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline {
  border: 2px solid var(--green-primary);
  color: var(--green-primary);
  background: transparent;
}
.btn-outline:hover { background: var(--green-primary); color: var(--white); }
.btn-dark {
  background: var(--black);
  color: var(--white);
}
.btn-dark:hover { background: oklch(25% 0.01 0); transform: translateY(-1px); }
.btn-white {
  background: var(--white);
  color: var(--green-primary);
}
.btn-white:hover { background: var(--cream-light); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }
.btn-lg { padding: 16px 32px; font-size: 1.05rem; }

/* ============ HEADER ============ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}
.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.35rem;
  color: var(--green-primary);
}
.logo-icon {
  width: 44px;
  height: 44px;
  background: var(--green-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-main { display: flex; align-items: center; gap: var(--space-xl); }
.nav-main a {
  font-weight: 500;
  font-size: 0.938rem;
  color: var(--gray-700);
  transition: color var(--transition-fast);
  padding: var(--space-sm) 0;
  position: relative;
}
.nav-main a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-base);
}
.nav-main a:hover { color: var(--green-primary); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green-primary); }
.nav-main a.active::after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: var(--space-md); }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 22px; height: 16px; display: flex; flex-direction: column; justify-content: space-between; }
.hamburger span { display: block; height: 2px; background: var(--black); border-radius: 2px; transition: var(--transition-base); }

/* ============ HERO ============ */
.hero {
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  padding: var(--space-4xl) 0;
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.hero::before {
  content: '';
  position: absolute;
  right: -5%;
  top: -10%;
  width: 55%;
  height: 120%;
  background: radial-gradient(ellipse, oklch(45% 0.14 160 / 0.08), transparent 70%);
  border-radius: 50%;
}
.hero-content { max-width: 560px; position: relative; z-index: 1; }
.hero h1 {
  font-size: clamp(2.5rem, 5vw, 3.8rem);
  color: var(--green-dark);
  margin-bottom: var(--space-lg);
  font-weight: 700;
}
.hero p {
  font-size: 1.15rem;
  color: var(--gray-600);
  margin-bottom: var(--space-xl);
  max-width: 440px;
}
.hero-image-placeholder {
  position: absolute;
  right: 5%;
  top: 50%;
  transform: translateY(-50%);
  width: 420px;
  height: 420px;
  background: linear-gradient(145deg, oklch(45% 0.14 160 / 0.12), oklch(88% 0.05 75 / 0.5));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green-primary);
  font-size: 3rem;
}

/* ============ SECTIONS ============ */
.section { padding: var(--space-4xl) 0; }
.section-alt { background: var(--off-white); }
.section-green { background: var(--green-primary); color: var(--white); }
.section-cream { background: var(--cream-light); }
.section-dark { background: var(--green-dark); color: var(--white); }
.section-title {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  margin-bottom: var(--space-md);
}
.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin-bottom: var(--space-2xl);
}

/* ============ PROMO CARDS ============ */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-2xl);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.promo-card h3 {
  font-size: 1.6rem;
  margin-bottom: var(--space-sm);
  color: inherit;
}
.promo-card p {
  margin-bottom: var(--space-lg);
  line-height: 1.5;
  opacity: 0.9;
}
.promo-card--citrus {
  background: linear-gradient(135deg, oklch(85% 0.12 70), oklch(90% 0.08 50));
  color: var(--brown-rich);
}
.promo-card--afternoon {
  background: linear-gradient(135deg, oklch(75% 0.1 30), oklch(85% 0.06 40));
  color: var(--brown-rich);
}
.promo-card--ai {
  background: linear-gradient(135deg, var(--green-dark), oklch(25% 0.08 160));
  color: var(--white);
}
.promo-card--fruity {
  background: linear-gradient(135deg, oklch(82% 0.14 60), oklch(75% 0.18 35));
  color: var(--brown-rich);
}
.promo-card--spring {
  background: linear-gradient(135deg, oklch(80% 0.12 290), oklch(85% 0.08 170));
  color: var(--green-dark);
}
.promo-card--nondairy {
  background: linear-gradient(135deg, var(--cream-warm), oklch(90% 0.04 85));
  color: var(--brown-rich);
}
.promo-card--full {
  grid-column: 1 / -1;
  min-height: 320px;
  text-align: center;
  align-items: center;
}

/* Image placeholder for promo cards */
.promo-image-placeholder {
  width: 100%;
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  opacity: 0.6;
}

/* ============ MENU PAGE ============ */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  padding: var(--space-2xl) 0;
}
.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-lg));
  align-self: start;
  max-height: calc(100vh - var(--header-height) - var(--space-2xl));
  overflow-y: auto;
}
.menu-sidebar-section { margin-bottom: var(--space-lg); }
.menu-sidebar-title {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: var(--space-sm);
  padding-left: var(--space-sm);
}
.menu-sidebar a {
  display: block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.938rem;
  color: var(--gray-600);
  transition: all var(--transition-fast);
}
.menu-sidebar a:hover { background: var(--gray-100); color: var(--green-primary); }
.menu-sidebar a.active { background: oklch(45% 0.14 160 / 0.08); color: var(--green-primary); font-weight: 600; }

.menu-category { margin-bottom: var(--space-3xl); }
.menu-category-title {
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--gray-200);
}
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-lg);
}
.menu-item {
  text-align: center;
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  cursor: pointer;
}
.menu-item:hover { background: var(--gray-100); transform: translateY(-2px); }
.menu-item-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto var(--space-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.menu-item-name { font-weight: 600; font-size: 0.9rem; }

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 0.85rem;
  color: var(--gray-400);
}
.breadcrumb a { color: var(--gray-500); }
.breadcrumb a:hover { color: var(--green-primary); text-decoration: underline; }
.breadcrumb span { margin: 0 var(--space-sm); }

/* ============ REWARDS PAGE ============ */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary), oklch(38% 0.16 165));
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
}
.rewards-hero h1 { font-size: clamp(2rem, 4vw, 3rem); margin-bottom: var(--space-md); }
.rewards-hero p { font-size: 1.15rem; max-width: 550px; margin: 0 auto var(--space-xl); opacity: 0.9; }

.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  text-align: center;
}
.hiw-step {
  padding: var(--space-xl);
}
.hiw-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green-primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0 auto var(--space-lg);
}
.hiw-step h3 { font-size: 1.2rem; margin-bottom: var(--space-sm); }
.hiw-step p { color: var(--gray-500); font-size: 0.95rem; }

/* Tiers */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}
.tier-card {
  border-radius: var(--radius-lg);
  padding: var(--space-2xl);
  text-align: center;
  border: 2px solid var(--gray-200);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}
.tier-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.tier-card--green { border-color: var(--green-primary); }
.tier-card--green .tier-badge { background: var(--green-primary); }
.tier-card--gold { border-color: var(--gold); }
.tier-card--gold .tier-badge { background: var(--gold); }
.tier-card--reserve { border-color: var(--reserve-purple); }
.tier-card--reserve .tier-badge { background: var(--reserve-purple); color: var(--white); }
.tier-badge {
  display: inline-block;
  padding: 6px 20px;
  border-radius: var(--radius-full);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
  margin-bottom: var(--space-lg);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.tier-stars { font-family: var(--font-heading); font-size: 1.6rem; font-weight: 700; margin-bottom: var(--space-sm); }
.tier-threshold { color: var(--gray-500); font-size: 0.9rem; margin-bottom: var(--space-lg); }
.tier-benefits { text-align: left; }
.tier-benefits li {
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}
.tier-benefits li::before {
  content: '\2713';
  color: var(--green-primary);
  font-weight: 700;
  flex-shrink: 0;
}
.tier-card--gold .tier-benefits li::before { color: var(--gold); }
.tier-card--reserve .tier-benefits li::before { color: var(--reserve-purple); }

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}
.redemption-tab {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  border: 2px solid var(--gray-200);
  background: var(--white);
  color: var(--gray-600);
  transition: all var(--transition-base);
}
.redemption-tab:hover { border-color: var(--green-primary); color: var(--green-primary); }
.redemption-tab.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
}
.redemption-content {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl);
  background: var(--off-white);
  border-radius: var(--radius-lg);
  min-height: 180px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.redemption-panel { display: none; }
.redemption-panel.active { display: flex; flex-direction: column; align-items: center; gap: var(--space-md); }
.redemption-stars {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--green-primary);
}
.redemption-reward { font-size: 1.15rem; font-weight: 500; }
.redemption-value { font-size: 0.9rem; color: var(--gray-500); }

/* Partnerships */
.partner-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.partner-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: var(--transition-base);
}
.partner-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}
.partner-card h4 { font-size: 1.05rem; margin-bottom: 4px; }
.partner-card p { font-size: 0.9rem; color: var(--gray-500); }

/* App Download */
.app-download {
  text-align: center;
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  border-radius: var(--radius-lg);
  padding: var(--space-3xl);
}
.app-badges { display: flex; gap: var(--space-md); justify-content: center; margin-top: var(--space-lg); }
.app-badge {
  padding: 12px 24px;
  background: var(--black);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.85rem;
  transition: var(--transition-base);
}
.app-badge:hover { background: oklch(25% 0 0); transform: translateY(-2px); }

/* ============ GIFT CARDS PAGE ============ */
.gift-hero {
  background: linear-gradient(135deg, oklch(80% 0.12 160), oklch(88% 0.05 75));
  padding: var(--space-4xl) 0;
  text-align: center;
}
.gift-hero h1 { font-size: clamp(2rem, 4vw, 3rem); color: var(--green-dark); margin-bottom: var(--space-md); }
.gift-hero p { font-size: 1.15rem; color: var(--gray-600); max-width: 550px; margin: 0 auto; }

.carousel-section { padding: var(--space-2xl) 0; }
.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}
.carousel-header h2 { font-size: 1.5rem; }
.carousel-nav { display: flex; gap: var(--space-sm); }
.carousel-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-base);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--green-primary); color: var(--green-primary); background: oklch(45% 0.14 160 / 0.05); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}
.gift-card {
  min-width: 220px;
  flex-shrink: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.gift-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.gift-card-image {
  width: 100%;
  aspect-ratio: 1.58;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--white);
  padding: var(--space-md);
  text-align: center;
}
.gift-card-label {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.85rem;
  font-weight: 500;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-top: none;
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

/* Gift card color themes */
.gc-spring { background: linear-gradient(135deg, oklch(72% 0.14 160), oklch(80% 0.10 130)); }
.gc-perk { background: linear-gradient(135deg, oklch(65% 0.12 30), oklch(75% 0.10 50)); }
.gc-friends { background: linear-gradient(135deg, oklch(55% 0.16 265), oklch(65% 0.12 280)); }
.gc-thankyou { background: linear-gradient(135deg, oklch(70% 0.14 80), oklch(78% 0.10 70)); }
.gc-star { background: linear-gradient(135deg, oklch(72% 0.16 80), oklch(65% 0.14 50)); }
.gc-work { background: linear-gradient(135deg, oklch(45% 0.14 160), oklch(50% 0.12 145)); }
.gc-birthday { background: linear-gradient(135deg, oklch(70% 0.18 330), oklch(75% 0.14 350)); }
.gc-celebrate { background: linear-gradient(135deg, oklch(68% 0.16 290), oklch(75% 0.12 310)); }
.gc-cheers { background: linear-gradient(135deg, oklch(60% 0.14 250), oklch(68% 0.10 265)); }
.gc-yay { background: linear-gradient(135deg, oklch(78% 0.16 70), oklch(72% 0.18 40)); }
.gc-treat { background: linear-gradient(135deg, oklch(50% 0.10 145), oklch(58% 0.08 160)); }
.gc-heritage { background: linear-gradient(135deg, oklch(35% 0.08 55), oklch(42% 0.10 40)); }
.gc-encourage { background: linear-gradient(135deg, oklch(75% 0.10 160), oklch(82% 0.06 140)); }
.gc-gotthis { background: linear-gradient(135deg, oklch(60% 0.18 30), oklch(68% 0.14 50)); }

/* Business Gifting */
.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2xl);
  align-items: center;
  padding: var(--space-3xl);
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-lg);
}
.business-gifting h2 { font-size: 1.8rem; margin-bottom: var(--space-md); }
.business-gifting p { opacity: 0.85; margin-bottom: var(--space-lg); line-height: 1.6; }
.business-image-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: oklch(25% 0.06 145 / 0.5);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: oklch(80% 0.04 160);
}

/* eGift Info */
.egift-info {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.egift-info p { color: var(--gray-500); line-height: 1.7; margin-bottom: var(--space-md); }
.egift-actions { display: flex; gap: var(--space-md); justify-content: center; flex-wrap: wrap; }
.egift-link {
  color: var(--green-primary);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.egift-link:hover { color: oklch(38% 0.14 160); }

/* ============ STORE LOCATOR ============ */
.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  min-height: calc(100vh - var(--header-height));
}
.locator-panel {
  padding: var(--space-xl);
  overflow-y: auto;
  border-right: 1px solid var(--gray-200);
}
.locator-search {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}
.locator-search input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.938rem;
  font-family: var(--font-body);
  transition: border-color var(--transition-fast);
  outline: none;
}
.locator-search input:focus { border-color: var(--green-primary); }
.locator-search input::placeholder { color: var(--gray-400); }
.filter-btn {
  padding: 12px 20px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.85rem;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  transition: all var(--transition-fast);
}
.filter-btn:hover { border-color: var(--green-primary); color: var(--green-primary); }
.filter-btn.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.order-type-toggle {
  display: flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-lg);
}
.order-type-btn {
  flex: 1;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  text-align: center;
  transition: all var(--transition-base);
  color: var(--gray-500);
}
.order-type-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--gray-100);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
}
.filter-panel.open { display: block; }
.filter-panel h4 { font-size: 0.9rem; margin-bottom: var(--space-sm); }
.filter-options { display: flex; flex-wrap: wrap; gap: var(--space-sm); }
.filter-chip {
  padding: 6px 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.filter-chip:hover, .filter-chip.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.search-suggestions {
  display: none;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-top: -var(--space-md);
  margin-bottom: var(--space-md);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.search-suggestions.open { display: block; }
.suggestion-item {
  padding: 12px 16px;
  cursor: pointer;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--gray-100);
  transition: background var(--transition-fast);
}
.suggestion-item:hover { background: var(--gray-100); }
.suggestion-item:last-child { border-bottom: none; }

.store-list { display: flex; flex-direction: column; }
.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--gray-200);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.store-card:hover { background: var(--gray-100); }
.store-card h4 { font-size: 1rem; margin-bottom: 4px; }
.store-card .store-address { font-size: 0.85rem; color: var(--gray-500); margin-bottom: 4px; }
.store-card .store-hours { font-size: 0.82rem; color: var(--gray-400); margin-bottom: var(--space-sm); }
.store-features { display: flex; gap: var(--space-sm); flex-wrap: wrap; }
.store-feature {
  font-size: 0.75rem;
  padding: 3px 10px;
  background: oklch(45% 0.14 160 / 0.08);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-weight: 500;
}

.map-container {
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.map-placeholder {
  width: 100%;
  height: 100%;
  min-height: 400px;
  background:
    linear-gradient(90deg, var(--gray-200) 1px, transparent 1px),
    linear-gradient(var(--gray-200) 1px, transparent 1px),
    var(--gray-100);
  background-size: 60px 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 1.1rem;
  flex-direction: column;
  gap: var(--space-sm);
}
.map-pin {
  width: 36px;
  height: 36px;
  background: var(--green-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  position: absolute;
  box-shadow: var(--shadow-md);
}
.map-pin::after {
  content: '';
  width: 14px;
  height: 14px;
  background: var(--white);
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* ============ FOOTER ============ */
.site-footer {
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: var(--space-3xl) 0 var(--space-xl);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}
.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-md);
  color: var(--black);
}
.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--gray-500);
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--green-primary); }
.footer-toggle { display: none; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-xl);
  border-top: 1px solid var(--gray-200);
  font-size: 0.82rem;
  color: var(--gray-400);
}
.footer-social { display: flex; gap: var(--space-md); }
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-fast);
  font-size: 0.85rem;
}
.footer-social a:hover { background: var(--green-primary); color: var(--white); }
.footer-legal { display: flex; gap: var(--space-lg); }
.footer-legal a:hover { color: var(--green-primary); }

/* ============ COOKIE BANNER ============ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px oklch(0% 0 0 / 0.12);
  padding: var(--space-lg) var(--space-xl);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
  transition: transform var(--transition-slow);
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-text h4 { font-family: var(--font-body); font-size: 0.95rem; font-weight: 700; margin-bottom: 4px; }
.cookie-text p { font-size: 0.85rem; color: var(--gray-500); }
.cookie-actions { display: flex; gap: var(--space-md); flex-shrink: 0; }

/* ============ MOBILE NAV ============ */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: var(--space-xl);
  flex-direction: column;
  gap: var(--space-md);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  padding: var(--space-md);
  font-size: 1.15rem;
  font-weight: 500;
  border-bottom: 1px solid var(--gray-100);
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .hero-image-placeholder { width: 320px; height: 320px; right: 2%; }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-panel { border-right: none; border-bottom: 1px solid var(--gray-200); }
  .map-container { min-height: 400px; }
  .business-gifting { grid-template-columns: 1fr; text-align: center; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }
  .nav-main, .nav-actions .btn { display: none; }
  .mobile-menu-btn { display: flex; }
  .hero { padding: var(--space-2xl) 0; min-height: auto; }
  .hero-image-placeholder { display: none; }
  .hero h1 { font-size: 2rem; }
  .promo-grid { grid-template-columns: 1fr; }
  .promo-card { min-height: 280px; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; overflow-x: auto; gap: var(--space-sm); padding-bottom: var(--space-md); border-bottom: 1px solid var(--gray-200); margin-bottom: var(--space-lg); max-height: none; }
  .menu-sidebar-section { margin-bottom: 0; display: flex; gap: var(--space-xs); }
  .menu-sidebar-title { display: none; }
  .menu-sidebar a { white-space: nowrap; padding: 6px 14px; border: 1px solid var(--gray-200); border-radius: var(--radius-full); font-size: 0.82rem; }
  .how-it-works-grid { grid-template-columns: 1fr; gap: var(--space-md); }
  .tiers-grid { grid-template-columns: 1fr; }
  .partner-cards { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-md) 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--gray-200);
    cursor: pointer;
  }
  .footer-col h4::after { content: '+'; font-size: 1.2rem; font-weight: 400; }
  .footer-col.open h4::after { content: '\2212'; }
  .footer-col .footer-links { display: none; padding: var(--space-sm) 0; }
  .footer-col.open .footer-links { display: block; }
  .footer-toggle { display: block; }
  .footer-bottom { flex-direction: column; gap: var(--space-md); text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 14px; font-size: 0.82rem; }
  .locator-layout { grid-template-columns: 1fr; }
  .gift-card { min-width: 180px; }
  .section { padding: var(--space-2xl) 0; }
  .app-badges { flex-direction: column; align-items: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .menu-grid { grid-template-columns: repeat(2, 1fr); gap: var(--space-md); }
  .menu-item-image { width: 80px; height: 80px; }
  .gift-card { min-width: 160px; }
}

raw_arguments.content:
/* GreenBean Coffee — Design System */
:root {
  /* Brand Colors (OKLCH) */
  --green-primary: oklch(45% 0.14 160);
  --green-dark: oklch(30% 0.06 145);
  --cream-warm: oklch(88% 0.05 75);
  --cream-light: oklch(96% 0.02 85);
  --brown-rich: oklch(35% 0.08 55);
  --brown-medium: oklch(50% 0.08 55);
  --white: oklch(99% 0 0);
  --off-white: oklch(97% 0.005 85);
  --black: oklch(15% 0.01 0);
  --gray-100: oklch(95% 0.005 0);
  --gray-200: oklch(90% 0.005 0);
  --gray-300: oklch(80% 0.005 0);
  --gray-400: oklch(65% 0.005 0);
  --gray-500: oklch(50% 0.01 0);
  --gray-600: oklch(40% 0.01 0);
  --gray-700: oklch(30% 0.01 0);
  --gold: oklch(72% 0.16 80);
  --gold-light: oklch(88% 0.08 80);
  --reserve-purple: oklch(45% 0.18 300);
  --reserve-light: oklch(90% 0.06 300);
  --accent-coral: oklch(70% 0.16 30);
  --accent-mango: oklch(78% 0.16 70);
  --accent-lavender: oklch(70% 0.12 290);
  --accent-blue: oklch(60% 0.14 250);

  /* Typography */
  --font-body: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Fraunces', 'Georgia', serif;

  /* Spacing Scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 30px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 50px oklch(0% 0 0 / 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 80px;
}

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300..700;1,9..40,300..700&family=Fraunces:ital,opsz,wght@0,9..144,300..700;1,9..144,300..700&display=swap');

/* Reset */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  color: var(--black);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.2; font-weight: 600; }

/* Utility */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-lg); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-sm { gap: var(--space-sm); }
.gap-md { gap: var(--space-md); }
.gap-lg { gap: var(--space-lg); }
.text-center { text-align: center; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition-base);
  white-space: nowrap;
  letter-spacing: 0.01em;
}
.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}
.btn-primary:hover { background: oklch(40% 0.14 160); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline {
  border: 2px solid var(--green-primary);
  color: var(--green-primary);
  background: transparent;
}
.btn-outline:hover { background: var(--green-primary); color: var(--white); }
.btn-dark {
  background: var(--black);
  color: var(--white);
}
.btn-dark:hover { background: oklch(25% 0.01 0); transform: translateY(-1px); }
.btn-white {
  background: var(--white);
  color: var(--green-primary);
}
.btn-white:hover { background: var(--cream-light); }
.btn-sm { padding: 8px 18px; font-size: 0.85rem; }
.btn-lg { padding: 16px 32px; font-size: 1.05rem; }

/* ============ HEADER ============ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}
.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.35rem;
  color: var(--green-primary);
}
.logo-icon {
  width: 44px;
  height: 44px;
  background: var(--green-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.1rem;
}
.nav-main { display: flex; align-items: center; gap: var(--space-xl); }
.nav-main a {
  font-weight: 500;
  font-size: 0.938rem;
  color: var(--gray-700);
  transition: color var(--transition-fast);
  padding: var(--space-sm) 0;
  position: relative;
}
.nav-main a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-base);
}
.nav-main a:hover { color: var(--green-primary); }
.nav-main a:hover::after { width: 100%; }
.nav-main a.active { color: var(--green-primary); }
.nav-main a.active::after { width: 100%; }
.nav-actions { display: flex; align-items: center; gap: var(--space-md); }
.mobile-menu-btn { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; }
.hamburger { width: 22px; height: 16px; display: flex; flex-direction: column; justify-content: space-between; }
.hamburger span { display: block; height: 2px; background: var(--black); border-radius: 2px; transition: var(--transition-base); }

/* ============ HERO ============ */
.hero {
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  padding: var(--space-4xl) 0;
  position: relative;
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
}
.hero::before {
  content: '';
  position: absolute;
  right: -5%;
  top: -10%;
  width: 55%;
  height: 120%;
  background: radial-gradient(ellipse, oklch(45% 0.14 160 / 0.08), transparent 70%);
  border-radius: 50%;
}
.hero-content { max-width: 560px; position: relative; z-index: 1; }
.hero h1 {
  font-size: clamp(2.5rem, 5vw, 3.8rem);
  color: var(--green-dark);
  margin-bottom: var(--space-lg);
  font-weight: 700;
}
.hero p {
  font-size: 1.15rem;
  color: var(--gray-600);
  margin-bottom: var(--space-xl);
  max-width: 440px;
}
.hero-image-placeholder {
  position: absolute;
  right: 5%;
  top: 50%;
  transform: translateY(-50%);
  width: 420px;
  height: 420px;
  background: linear-gradient(145deg, oklch(45% 0.14 160 / 0.12), oklch(88% 0.05 75 / 0.5));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green-primary);
  font-size: 3rem;
}

/* ============ SECTIONS ============ */
.section { padding: var(--space-4xl) 0; }
.section-alt { background: var(--off-white); }
.section-green { background: var(--green-primary); color: var(--white); }
.section-cream { background: var(--cream-light); }
.section-dark { background: var(--green-dark); color: var(--white); }
.section-title {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  margin-bottom: var(--space-md);
}
.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin-bottom: var(--space-2xl);
}

/* ============ PROMO CARDS ============ */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: var(--space-2xl);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.promo-card h3 {
  font-size: 1.6rem;
  margin-bottom: var(--space-sm);
  color: inherit;
}
.promo-card p {
  margin-bottom: var(--space-lg);
  line-height: 1.5;
  opacity: 0.9;
}
.promo-card--citrus {
  background: linear-gradient(135deg, oklch(85% 0.12 70), oklch(90% 0.08 50));
  color: var(--brown-rich);
}
.promo-card--afternoon {
  background: linear-gradient(135deg, oklch(75% 0.1 30), oklch(85% 0.06 40));
  color: var(--brown-rich);
}
.promo-card--ai {
  background: linear-gradient(135deg, var(--green-dark), oklch(25% 0.08 160));
  color: var(--white);
}
.promo-card--fruity {
  background: linear-gradient(135deg, oklch(82% 0.14 60), oklch(75% 0.18 35));
  color: var(--brown-rich);
}
.promo-card--spring {
  background: linear-gradient(135deg, oklch(80% 0.12 290), oklch(85% 0.08 170));
  color: var(--green-dark);
}
.promo-card--nondairy {
  background: linear-gradient(135deg, var(--cream-warm), oklch(90% 0.04 85));
  color: var(--brown-rich);
}
.promo-card--full {
  grid-column: 1 / -1;
  min-height: 320px;
  text-align: center;
  align-items: center;
}

/* Image placeholder for promo cards */
.promo-image-placeholder {
  width: 100%;
  height: 200px;
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  opacity: 0.6;
}

/* ============ MENU PAGE ============ */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  padding: var(--space-2xl) 0;
}
.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-lg));
  align-self: start;
  max-height: calc(100vh - var(--header-height) - var(--space-2xl));
  overflow-y: auto;
}
.menu-sidebar-section { margin-bottom: var(--space-lg); }
.menu-sidebar-title {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: var(--space-sm);
  padding-left: var(--space-sm);
}
.menu-sidebar a {
  display: block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.938rem;
  color: var(--gray-600);
  transition: all var(--transition-fast);
}
.menu-sidebar a:hover { background: var(--gray-100); color: var(--green-primary); }
.menu-sidebar a.active { background: oklch(45% 0.14 160 / 0.08); color: var(--green-primary); font-weight: 600; }

.menu-category { margin-bottom: var(--space-3xl); }
.menu-category-title {
  font-size: 1.5rem;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--gray-200);
}
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-lg);
}
.menu-item {
  text-align: center;
  padding: var(--space-lg);
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  cursor: pointer;
}
.menu-item:hover { background: var(--gray-100); transform: translateY(-2px); }
.menu-item-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto var(--space-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
}
.menu-item-name { font-weight: 600; font-size: 0.9rem; }

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 0.85rem;
  color: var(--gray-400);
}
.breadcrumb a { color: var(--gray-500); }
.breadcrumb a:hover { color: var(--green-primary); text-decoration: underline; }
.breadcrumb span { margin: 0 var(--space-sm); }

/* ============ REWARDS PAGE ============ */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary), oklch(38% 0.16 165));
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
}
.rewards-hero h1 { font-size: clamp(2rem, 4vw, 3rem); margin-bottom: var(--space-md); }
.rewards-hero p { font-size: 1.15rem; max-width: 550px; margin: 0 auto var(--space-xl); opacity: 0.9; }

.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  text-align: center;
}
.hiw-step {
  padding: var(--space-xl);
}
.hiw-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green-primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0 auto var(--space-lg);
}
.hiw-step h3 { font-size: 1.2rem; margin-bottom: var(--space-sm); }
.hiw-step p { color: var(--gray-500); font-size: 0.95rem; }

/* Tiers */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}
.tier-card {
  border-radius: var(--radius-lg);
  padding: var(--space-2xl);
  text-align: center;
  border: 2px solid var(--gray-200);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}
.tier-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.tier-card--green { border-color: var(--green-primary); }
.tier-card--green .tier-badge { background: var(--green-primary); }
.tier-card--gold { border-color: var(--gold); }
.tier-card--gold .tier-badge { background: var(--gold); }
.tier-card--reserve { border-color: var(--reserve-purple); }
.tier-card--reserve .tier-badge { background: var(--reserve-purple); color: var(--white); }
.tier-badge {
  display: inline-block;
  padding: 6px 20px;
  border-radius: var(--radius-full);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
  margin-bottom: var(--space-lg);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.tier-stars { font-family: var(--font-heading); font-size: 1.6rem; font-weight: 700; margin-bottom: var(--space-sm); }
.tier-threshold { color: var(--gray-500); font-size: 0.9rem; margin-bottom: var(--space-lg); }
.tier-benefits { text-align: left; }
.tier-benefits li {
  padding: var(--space-sm) 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}
.tier-benefits li::before {
  content: '\2713';
  color: var(--green-primary);
  font-weight: 700;
  flex-shrink: 0;
}
.tier-card--gold .tier-benefits li::before { color: var(--gold); }
.tier-card--reserve .tier-benefits li::before { color: var(--reserve-purple); }

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}
.redemption-tab {
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  border: 2px solid var(--gray-200);
  background: var(--white);
  color: var(--gray-600);
  transition: all var(--transition-base);
}
.redemption-tab:hover { border-color: var(--green-primary); color: var(--green-primary); }
.redemption-tab.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
}
.redemption-content {
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl);
  background: var(--off-white);
  border-radius: var(--radius-lg);
  min-height: 180px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.redemption-panel { display: none; }
.redemption-panel.active { display: flex; flex-direction: column; align-items: center; gap: var(--space-md); }
.redemption-stars {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--green-primary);
}
.redemption-reward { font-size: 1.15rem; font-weight: 500; }
.redemption-value { font-size: 0.9rem; color: var(--gray-500); }

/* Partnerships */
.partner-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}
.partner-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: var(--transition-base);
}
.partner-card:hover { box-shadow: var(--shadow-md); }
.partner-logo {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}
.partner-card h4 { font-size: 1.05rem; margin-bottom: 4px; }
.partner-card p { font-size: 0.9rem; color: var(--gray-500); }

/* App Download */
.app-download {
  text-align: center;
  background: linear-gradient(135deg, var(--cream-warm), var(--cream-light));
  border-radius: var(--radius-lg);
  padding: var(--space-3xl);
}
.app-badges { display: flex; gap: var(--space-md); justify-content: center; margin-top: var(--space-lg); }
.app-badge {
  padding: 12px 24px;
  background: var(--black);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.85rem;
  transition: var(--transition-base);
}
.app-badge:hover { background: oklch(25% 0 0); transform: translateY(-2px); }

/* ============ GIFT CARDS PAGE ============ */
.gift-hero {
  background: linear-gradient(135deg, oklch(80% 0.12 160), oklch(88% 0.05 75));
  padding: var(--space-4xl) 0;
  text-align: center;
}
.gift-hero h1 { font-size: clamp(2rem, 4vw, 3rem); color: var(--green-dark); margin-bottom: var(--space-md); }
.gift-hero p { font-size: 1.15rem; color: var(--gray-600); max-width: 550px; margin: 0 auto; }

.carousel-section { padding: var(--space-2xl) 0; }
.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}
.carousel-header h2 { font-size: 1.5rem; }
.carousel-nav { display: flex; gap: var(--space-sm); }
.carousel-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-base);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--green-primary); color: var(--green-primary); background: oklch(45% 0.14 160 / 0.05); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }

.carousel-track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--transition-slow);
}
.gift-card {
  min-width: 220px;
  flex-shrink: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}
.gift-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.gift-card-image {
  width: 100%;
  aspect-ratio: 1.58;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--white);
  padding: var(--space-md);
  text-align: center;
}
.gift-card-label {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.85rem;
  font-weight: 500;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-top: none;
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
}

/* Gift card color themes */
.gc-spring { background: linear-gradient(135deg, oklch(72% 0.14 160), oklch(80% 0.10 130)); }
.gc-perk { background: linear-gradient(135deg, oklch(65% 0.12 30), oklch(75% 0.10 50)); }
.gc-friends { background: linear-gradient(135deg, oklch(55% 0.16 265), oklch(65% 0.12 280)); }
.gc-thankyou { background: linear-gradient(135deg, oklch(70% 0.14 80), oklch(78% 0.10 70)); }
.gc-star { background: linear-gradient(135deg, oklch(72% 0.16 80), oklch(65% 0.14 50)); }
.gc-work { background: linear-gradient(135deg, oklch(45% 0.14 160), oklch(50% 0.12 145)); }
.gc-birthday { background: linear-gradient(135deg, oklch(70% 0.18 330), oklch(75% 0.14 350)); }
.gc-celebrate { background: linear-gradient(135deg, oklch(68% 0.16 290), oklch(75% 0.12 310)); }
.gc-cheers { background: linear-gradient(135deg, oklch(60% 0.14 250), oklch(68% 0.10 265)); }
.gc-yay { background: linear-gradient(135deg, oklch(78% 0.16 70), oklch(72% 0.18 40)); }
.gc-treat { background: linear-gradient(135deg, oklch(50% 0.10 145), oklch(58% 0.08 160)); }
.gc-heritage { background: linear-gradient(135deg, oklch(35% 0.08 55), oklch(42% 0.10 40)); }
.gc-encourage { background: linear-gradient(135deg, oklch(75% 0.10 160), oklch(82% 0.06 140)); }
.gc-gotthis { background: linear-gradient(135deg, oklch(60% 0.18 30), oklch(68% 0.14 50)); }

/* Business Gifting */
.business-gifting {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2xl);
  align-items: center;
  padding: var(--space-3xl);
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-lg);
}
.business-gifting h2 { font-size: 1.8rem; margin-bottom: var(--space-md); }
.business-gifting p { opacity: 0.85; margin-bottom: var(--space-lg); line-height: 1.6; }
.business-image-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: oklch(25% 0.06 145 / 0.5);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: oklch(80% 0.04 160);
}

/* eGift Info */
.egift-info {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.egift-info p { color: var(--gray-500); line-height: 1.7; margin-bottom: var(--space-md); }
.egift-actions { display: flex; gap: var(--space-md); justify-content: center; flex-wrap: wrap; }
.egift-link {
  color: var(--green-primary);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.egift-link:hover { color: oklch(38% 0.14 160); }

/* ============ STORE LOCATOR ============ */
.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  min-height: calc(100vh - var(--header-height));
}
.locator-panel {
  padding: var(--space-xl);
  overflow-y: auto;
  border-right: 1px solid var(--gray-200);
}
.locator-search {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}
.locator-search input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.938rem;
  font-family: var(--font-body);
  transition: border-color var(--transition-fast);
  outline: none;
}
.locator-search input:focus { border-color: var(--green-primary); }
.locator-search input::placeholder { color: var(--gray-400); }
.filter-btn {
  padding: 12px 20px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.85rem;
  color: var(--gray-600);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  transition: all var(--transition-fast);
}
.filter-btn:hover { border-color: var(--green-primary); color: var(--green-primary); }
.filter-btn.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.order-type-toggle {
  display: flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-lg);
}
.order-type-btn {
  flex: 1;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.9rem;
  text-align: center;
  transition: all var(--transition-base);
  color: var(--gray-500);
}
.order-type-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--gray-100);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-lg);
}
.filter-panel.open { display: block; }
.filter-panel h4 { font-size: 0.9rem; margin-bottom: var(--space-sm); }
.filter-options { display: flex; flex-wrap: wrap; gap: var(--space-sm); }
.filter-chip {
  padding: 6px 14px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.filter-chip:hover, .filter-chip.active { background: var(--green-primary); color: var(--white); border-color: var(--green-primary); }

.search-suggestions {
  display: none;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-top: -var(--space-md);
  margin-bottom: var(--space-md);
  box-shadow: var(--shadow-md);
  overflow: hidden;
}
.search-suggestions.open { display: block; }
.suggestion-item {
  padding: 12px 16px;
  cursor: pointer;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--gray-100);
  transition: background var(--transition-fast);
}
.suggestion-item:hover { background: var(--gray-100); }
.suggestion-item:last-child { border-bottom: none; }

.store-list { display: flex; flex-direction: column; }
.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--gray-200);
  transition: background var(--transition-fast);
  cursor: pointer;
}
.store-card:hover { background: var(--gray-100); }
.store-card h4 { font-size: 1rem; margin-bottom: 4px; }
.store-card .store-address { font-size: 0.85rem; color: var(--gray-500); margin-bottom: 4px; }
.store-card .store-hours { font-size: 0.82rem; color: var(--gray-400); margin-bottom: var(--space-sm); }
.store-features { display: flex; gap: var(--space-sm); flex-wrap: wrap; }
.store-feature {
  font-size: 0.75rem;
  padding: 3px 10px;
  background: oklch(45% 0.14 160 / 0.08);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-weight: 500;
}

.map-container {
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.map-placeholder {
  width: 100%;
  height: 100%;
  min-height: 400px;
  background:
    linear-gradient(90deg, var(--gray-200) 1px, transparent 1px),
    linear-gradient(var(--gray-200) 1px, transparent 1px),
    var(--gray-100);
  background-size: 60px 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 1.1rem;
  flex-direction: column;
  gap: var(--space-sm);
}
.map-pin {
  width: 36px;
  height: 36px;
  background: var(--green-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  position: absolute;
  box-shadow: var(--shadow-md);
}
.map-pin::after {
  content: '';
  width: 14px;
  height: 14px;
  background: var(--white);
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* ============ FOOTER ============ */
.site-footer {
  background: var(--white);
  border-top: 1px solid var(--gray-200);
  padding: var(--space-3xl) 0 var(--space-xl);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-3xl);
}
.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-md);
  color: var(--black);
}
.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--gray-500);
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--green-primary); }
.footer-toggle { display: none; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-xl);
  border-top: 1px solid var(--gray-200);
  font-size: 0.82rem;
  color: var(--gray-400);
}
.footer-social { display: flex; gap: var(--space-md); }
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-600);
  transition: all var(--transition-fast);
  font-size: 0.85rem;
}
.footer-social a:hover { background: var(--green-primary); color: var(--white); }
.footer-legal { display: flex; gap: var(--space-lg); }
.footer-legal a:hover { color: var(--green-primary); }

/* ============ COOKIE BANNER ============ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px oklch(0% 0 0 / 0.12);
  padding: var(--space-lg) var(--space-xl);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-xl);
  transition: transform var(--transition-slow);
}
.cookie-banner.hidden { transform: translateY(100%); }
.cookie-text h4 { font-family: var(--font-body); font-size: 0.95rem; font-weight: 700; margin-bottom: 4px; }
.cookie-text p { font-size: 0.85rem; color: var(--gray-500); }
.cookie-actions { display: flex; gap: var(--space-md); flex-shrink: 0; }

/* ============ MOBILE NAV ============ */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 99;
  padding: var(--space-xl);
  flex-direction: column;
  gap: var(--space-md);
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  padding: var(--space-md);
  font-size: 1.15rem;
  font-weight: 500;
  border-bottom: 1px solid var(--gray-100);
}

/* ============ RESPONSIVE ============ */
@media (max-width: 1024px) {
  .hero-image-placeholder { width: 320px; height: 320px; right: 2%; }
  .locator-layout { grid-template-columns: 1fr; }
  .locator-panel { border-right: none; border-bottom: 1px solid var(--gray-200); }
  .map-container { min-height: 400px; }
  .business-gifting { grid-template-columns: 1fr; text-align: center; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }
  .nav-main, .nav-actions .btn { display: none; }
  .mobile-menu-btn { display: flex; }
  .hero { padding: var(--space-2xl) 0; min-height: auto; }
  .hero-image-placeholder { display: none; }
  .hero h1 { font-size: 2rem; }
  .promo-grid { grid-template-columns: 1fr; }
  .promo-card { min-height: 280px; }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; display: flex; overflow-x: auto; gap: var(--space-sm); padding-bottom: var(--space-md); border-bottom: 1px solid var(--gray-200); margin-bottom: var(--space-lg); max-height: none; }
  .menu-sidebar-section { margin-bottom: 0; display: flex; gap: var(--space-xs); }
  .menu-sidebar-title { display: none; }
  .menu-sidebar a { white-space: nowrap; padding: 6px 14px; border: 1px solid var(--gray-200); border-radius: var(--radius-full); font-size: 0.82rem; }
  .how-it-works-grid { grid-template-columns: 1fr; gap: var(--space-md); }
  .tiers-grid { grid-template-columns: 1fr; }
  .partner-cards { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-md) 0;
    margin-bottom: 0;
    border-bottom: 1px solid var(--gray-200);
    cursor: pointer;
  }
  .footer-col h4::after { content: '+'; font-size: 1.2rem; font-weight: 400; }
  .footer-col.open h4::after { content: '\2212'; }
  .footer-col .footer-links { display: none; padding: var(--space-sm) 0; }
  .footer-col.open .footer-links { display: block; }
  .footer-toggle { display: block; }
  .footer-bottom { flex-direction: column; gap: var(--space-md); text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 14px; font-size: 0.82rem; }
  .locator-layout { grid-template-columns: 1fr; }
  .gift-card { min-width: 180px; }
  .section { padding: var(--space-2xl) 0; }
  .app-badges { flex-direction: column; align-items: center; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .menu-grid { grid-template-columns: repeat(2, 1fr); gap: var(--space-md); }
  .menu-item-image { width: 80px; height: 80px; }
  .gift-card { min-width: 160px; }
}
